function sumOfNumberAndReverse(num) {
  for (let candidate = 0; candidate <= num; candidate++) {
    let rest = candidate;
    let reversed = 0;
    while (rest > 0) {
      reversed = reversed * 10 + (rest % 10);
      rest = Math.floor(rest / 10);
    }
    if (candidate + reversed === num) {
      return true;
    }
  }
  return false;
}

