function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const limit = size === 'large' ? 100000 : 300;
  if (rand() < 0.5) {
    // Build a value that is reachable by picking x first.
    for (;;) {
      const x = size === 'large' ? 20000 + pick(80001) : pick(limit + 1);
      let rest = x;
      let reversed = 0;
      while (rest > 0) {
        reversed = reversed * 10 + (rest % 10);
        rest = Math.floor(rest / 10);
      }
      if (x + reversed <= limit) return [x + reversed];
    }
  }
  return [size === 'large' ? 50000 + pick(50001) : pick(limit + 1)];
}
